phase('Adversarial')
const res = []
let sig = 0
const trabajador = async () => { while (sig < AGENTES.length) { const k = sig++; const a = AGENTES[k]; res[k] = await agent(a.prompt, { label: a.label, phase: 'Adversarial', schema: a.schema, agentType: 'general-purpose' }) } }
await Promise.all([trabajador(), trabajador(), trabajador()])
return Object.fromEntries(AGENTES.map((a, i) => [a.label, res[i]]))
